const BANK_ML = [{"id": "ml-001", "cat": "ml", "diff": 2, "q": "What is the stated purpose of this 6-hour course?", "options": ["To replace a university degree", "To cover ML algorithms + practical implementation so you can clear interviews", "To teach deep learning research", "To prepare only for coding rounds"], "a": 1, "expl": "The intro frames the session as interview-ready fundamentals: algorithms, intuition, and practicals.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-002", "cat": "ml", "diff": 2, "q": "The course ladder moves from intuition to math to code. Why that order?", "options": ["Code is unimportant", "Understanding the problem an algorithm solves makes the math and code stick", "Math is optional in interviews", "It matches a textbook chapter order"], "a": 1, "expl": "Interviewers probe exactly this chain: what is it → why do we need it → show me.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-003", "cat": "ml", "diff": 1, "q": "Which of these course topics does your Project-01 (hybrid recommender) directly exercise?", "options": ["Only linear regression", "Evaluation protocol, regularization, tuning, and ensemble thinking", "Only SQL", "Only neural networks"], "a": 1, "expl": "Your reco engine used a temporal split, an SVD reg grid tuned on validation, and ensemble-style fusion of two model arms.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-004", "cat": "ml", "diff": 3, "q": "A production XGBoost churn model (like yours at MyOperator) builds on which course fundamentals?", "options": ["Boosting algorithms and classification metrics", "Image convolution", "Reinforcement learning", "No fundamentals needed"], "a": 0, "expl": "XGBoost is boosted trees — covered via AdaBoost/boosting — and its production value is judged by classification metrics.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-005", "cat": "ml", "diff": 2, "q": "What is the risk of learning algorithms WITHOUT practicals?", "options": ["None — theory is enough", "You can define a term but cannot defend why you chose it or what breaks it", "Practicals are illegal in interviews", "It only matters for research jobs"], "a": 1, "expl": "Interviews pivot from definition to defense: why this algorithm, what are its failure modes, how did you evaluate it.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-006", "cat": "ml", "diff": 1, "q": "Your own equivalent of this course intro is…", "options": ["Skipping to XGBoost code", "The Project-01 plan doc: problem → pipeline → models → evaluation protocol", "Reading the sklearn docs once", "Memorizing formulas"], "a": 1, "expl": "You already built the same arc end-to-end: 09_project_plan_01 → code → measured +100.8% lift.", "remedy": "Notes + quiz: ../krish-ml-6h/01-intro.html"}, {"id": "ml-007", "cat": "ml", "diff": 2, "q": "Which statement describes the relationship correctly?", "options": ["ML is a subset of DL", "DL is a subset of ML, and ML is a subset of AI", "AI and ML are unrelated", "DL contains AI"], "a": 1, "expl": "Containment: Deep Learning ⊂ Machine Learning ⊂ Artificial Intelligence.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-008", "cat": "ml", "diff": 2, "q": "Netflix recommending shows and Tesla self-driving are examples of…", "options": ["Data engineering", "AI applications performing tasks without human intervention", "Only statistics", "Database design"], "a": 1, "expl": "Both are AI applications acting autonomously — the umbrella definition given in the video.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-009", "cat": "ml", "diff": 1, "q": "Machine Learning is best defined as…", "options": ["Any program with if-else rules", "Statistical tools to analyze, visualize, predict and forecast from data", "Only neural networks", "A hardware category"], "a": 1, "expl": "ML = the statistical-tools layer inside AI; forecasting sales/weather and recommenders are the examples given.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-010", "cat": "ml", "diff": 3, "q": "What makes Deep Learning a separate subset inside ML?", "options": ["It avoids data", "It mimics the human brain using multi-layered neural networks", "It never uses GPUs", "It only does regression"], "a": 1, "expl": "DL = ML via multi-layered neural networks inspired by the brain; big data + GPUs are its natural habitat.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-011", "cat": "ml", "diff": 2, "q": "Face recognition and voice assistants are typically…", "options": ["Classic ML with hand-designed rules", "Deep Learning applications", "Unsupervised statistics only", "Not AI at all"], "a": 1, "expl": "Perception tasks like face/voice recognition are the flagship DL examples.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-012", "cat": "ml", "diff": 1, "q": "A Data Scientist, compared to AI/ML/DL engineers, is characterized as…", "options": ["Someone who never models", "A role that works across AI, ML and DL — data collection through modeling to communication", "Only a visualization job", "Only a database admin"], "a": 1, "expl": "DS spans the stack: cleaning, EDA, modeling (ML or DL), and business communication.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-013", "cat": "ml", "diff": 2, "q": "Online advertising targeting is cited as an example of…", "options": ["AI application — actions chosen without human intervention", "Manual marketing", "Hardware optimization", "Reinforcement learning only"], "a": 0, "expl": "Ads sit in the AI umbrella: systems decide what to show without a human in the loop.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-014", "cat": "ml", "diff": 2, "q": "In an interview you should describe the layers as…", "options": ["AI = ML = DL (synonyms)", "DL ⊂ ML ⊂ AI, with one example per layer", "ML replaced AI in 2015", "DL has no relation to ML"], "a": 1, "expl": "Clean containment plus examples is the expected crisp answer; mixing levels is the classic mistake.", "remedy": "Notes + quiz: ../krish-ml-6h/02-ai-ml-dl-ds.html"}, {"id": "ml-015", "cat": "ml", "diff": 1, "q": "Deep learning mimics the human brain using…", "options": ["Decision trees", "Multi-layered neural networks", "SQL joins", "Rule-based systems"], "a": 1, "expl": "The defining idea of DL: layered neural networks, each learning more abstract representations.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-016", "cat": "ml", "diff": 3, "q": "Deep learning research actually dates back to…", "options": ["The 2010s", "The 1950s–60s", "2012 only", "The 1990s internet era"], "a": 1, "expl": "The video notes DL ideas go back to the 1950s-60s; recent data + GPU compute made them practical.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-017", "cat": "ml", "diff": 2, "q": "What recently made deep learning practical at scale?", "options": ["Fewer layers", "More data + GPU compute", "Slower computers", "Removal of neural networks"], "a": 1, "expl": "Data volume and GPU compute are the two enablers cited for DL’s rise.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-018", "cat": "ml", "diff": 1, "q": "For tabular business data (like churn), the typically right-sized choice is…", "options": ["Always deep learning", "Classical ML (e.g., XGBoost) — often better and more explainable", "Only neural networks work", "No modeling is possible"], "a": 1, "expl": "Classical ML usually wins on tabular data; your XGBoost churn model is the production proof.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-019", "cat": "ml", "diff": 2, "q": "Your Project-01 used SVD + TF-IDF instead of neural networks. The strongest interview defense is…", "options": ["I did not know deep learning", "Right-sizing: classical ML fit the data scale, was explainable, and beat the baseline by +100.8%", "Deep learning is illegal for recommenders", "TF-IDF is a neural network"], "a": 1, "expl": "Tool choice as an engineering decision — measured lift, explainability, and data scale justify it.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-020", "cat": "ml", "diff": 2, "q": "The relationship ML : DL is correctly drawn as…", "options": ["Siblings with no overlap", "DL ⊂ ML", "ML ⊂ DL", "Identical"], "a": 1, "expl": "Deep learning is the subset of ML that uses multi-layered neural networks.", "remedy": "Notes + quiz: ../krish-ml-6h/03-ml-and-dl.html"}, {"id": "ml-021", "cat": "ml", "diff": 1, "q": "Supervised learning requires…", "options": ["No labels at all", "Both independent features (X) and a known dependent output (y)", "Only one feature", "A GPU"], "a": 1, "expl": "Supervised = learning a mapping from labeled examples, like age → weight in the video.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-022", "cat": "ml", "diff": 3, "q": "Predicting a person’s weight from their age is…", "options": ["Classification", "Regression — the output is continuous", "Clustering", "Dimensionality reduction"], "a": 1, "expl": "Weight is a continuous number → regression (the video’s own example).", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-023", "cat": "ml", "diff": 2, "q": "Given study-hours and play-hours, predicting pass/fail is…", "options": ["Regression", "Clustering", "Classification — binary with fixed categories", "PCA"], "a": 2, "expl": "Pass/fail is a fixed category → binary classification.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-024", "cat": "ml", "diff": 1, "q": "Multiclass classification means…", "options": ["The output has more than two fixed categories", "Multiple regression models", "The data has many rows", "Two outputs"], "a": 0, "expl": "Binary = 2 classes; multiclass = 3+ fixed categories (e.g., digits 0–9).", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-025", "cat": "ml", "diff": 2, "q": "Unsupervised learning is defined by…", "options": ["Having a very large y", "Having NO output variable — only features", "Using deep networks", "Requiring GPUs"], "a": 1, "expl": "No labels: the algorithm must find structure (clusters) or compress features (PCA) by itself.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-026", "cat": "ml", "diff": 2, "q": "Customer segmentation for targeted ad campaigns is the standard example of…", "options": ["Regression", "Classification", "Clustering", "Reinforcement learning"], "a": 2, "expl": "Group similar customers, then market to each group differently — the video’s clustering use-case.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-027", "cat": "ml", "diff": 1, "q": "Dimensionality reduction, e.g. PCA turning 1000 features into 100, is used to…", "options": ["Increase the number of features", "Keep the essence of the data with fewer features", "Create labels", "Split data into clusters"], "a": 1, "expl": "PCA compresses feature count while preserving information — the second unsupervised flavor.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-028", "cat": "ml", "diff": 3, "q": "Your Project-01 recommender predicts scores but is judged by hit-rate@10. Correctly framed, it is…", "options": ["Pure regression, nothing else", "A ranking problem: scores are regression-flavored, evaluation is classification-flavored", "Unsupervised with no evaluation", "Reinforcement learning"], "a": 1, "expl": "Matrix-factorization scoring is regression-style; HR@10 judges top-k like classification — a nuance interviewers enjoy.", "remedy": "Notes + quiz: ../krish-ml-6h/04-regression-vs-classification.html"}, {"id": "ml-029", "cat": "ml", "diff": 2, "q": "In hθ(x) = θ0 + θ1·x, what does θ0 represent?", "options": ["The slope of the line", "The intercept — where the line crosses the y-axis", "The number of features", "The learning rate"], "a": 1, "expl": "θ0 is the intercept (y-axis crossing), θ1 is the slope/coefficient.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-030", "cat": "ml", "diff": 1, "q": "Why is the cost divided by 2m instead of m?", "options": ["To make the cost smaller", "It cancels the exponent 2 when the derivative is taken", "To handle negative errors", "Tradition only"], "a": 1, "expl": "The ½ is cosmetic for calculus: the derivative of (… )² brings a 2, which the ½ cancels.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-031", "cat": "ml", "diff": 2, "q": "For points (1,1), (2,2), (3,3), the line θ1 = 1 (θ0 = 0) gives cost J =", "options": ["0.58", "2.3", "0", "1"], "a": 2, "expl": "Predictions match the points exactly, so every error is 0 → J = 0 (the video’s worked example).", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-032", "cat": "ml", "diff": 2, "q": "The cost surface of linear regression is special because…", "options": ["It has many local minima", "It is a convex parabola with a single global minimum", "It is random", "It has no minimum"], "a": 1, "expl": "Convexity guarantees ONE global minimum — gradient descent cannot get trapped locally (unlike deep nets).", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-033", "cat": "ml", "diff": 1, "q": "If the learning rate α is too large, gradient descent will…", "options": ["Converge instantly", "Overshoot the minimum and possibly never converge", "Always find a better minimum", "Ignore the data"], "a": 1, "expl": "Too-big steps jump across the valley; too-small steps just converge slowly.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-034", "cat": "ml", "diff": 3, "q": "The gradient-descent update rule for each parameter is…", "options": ["θj := θj + α · J", "θj := θj − α · ∂J/∂θj", "θj := J − α", "θj := θj × ∂J/∂θj"], "a": 1, "expl": "Step AGAINST the gradient (downhill) scaled by the learning rate α.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-035", "cat": "ml", "diff": 2, "q": "R² can be negative when…", "options": ["There are many features", "The fitted line is WORSE than simply predicting the mean", "The data is too clean", "α is too small"], "a": 1, "expl": "R² = 1 − SSres/SStot; if SSres > SStot, R² goes negative — the model is worse than the mean-line.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-036", "cat": "ml", "diff": 1, "q": "Adding useless features (bedrooms, location, gender to a salary model) will…", "options": ["Always improve adjusted R²", "Never change R²", "Raise raw R² but can LOWER adjusted R²", "Make R² negative by definition"], "a": 2, "expl": "Raw R² never falls when you add features; adjusted R² penalizes useless ones — the video showed 86→82.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-037", "cat": "ml", "diff": 2, "q": "Which is always ≥ the other?", "options": ["Adjusted R² ≥ R²", "R² ≥ adjusted R²", "They are always equal", "Neither is comparable"], "a": 1, "expl": "Adjusted R² subtracts a correction for feature count, so it can only be ≤ raw R².", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-038", "cat": "ml", "diff": 2, "q": "Deep learning costs differ from linear regression costs because…", "options": ["DL costs are convex", "DL surfaces have local minima — hence optimizers like Adam/RMSprop", "DL never uses gradient descent", "There is no cost in DL"], "a": 1, "expl": "Linear regression = convex parabola (one minimum); neural nets create non-convex surfaces with local minima.", "remedy": "Notes + quiz: ../krish-ml-6h/05-linear-regression.html"}, {"id": "ml-039", "cat": "ml", "diff": 1, "q": "A model fitted through just 2 training points reaches cost J = 0. Why is that still a bad model?", "options": ["Linear regression can never actually reach J = 0", "It memorizes the 2 points and fails on new data — overfitting", "The cost should be maximized, not minimized", "J = 0 proves the model is generalized"], "a": 1, "expl": "A perfect fit on 2 points is low bias but high variance: the line bends around those points and will not generalize to new data.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-040", "cat": "ml", "diff": 3, "q": "Train score 90, test score 80. What is the diagnosis?", "options": ["Underfitting", "Generalized model", "Overfitting", "A coding bug in the test loop"], "a": 2, "expl": "A big gap between train and test = overfitting. Compare the table: 92/91 is generalized, 70/65 is underfit.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-041", "cat": "ml", "diff": 2, "q": "Which penalty does Lasso (L1) add to the cost function?", "options": ["lambda × slope²", "lambda × |slope|", "lambda ÷ number of features", "lambda × intercept"], "a": 1, "expl": "L1 uses the absolute value of the slope. Ridge (L2) uses the square: lambda × slope².", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-042", "cat": "ml", "diff": 1, "q": "What happens to a Ridge model if lambda is set to a huge value?", "options": ["The slopes shrink toward 0, the line goes almost flat, and the model underfits", "It becomes exactly plain linear regression", "Coefficients get selected automatically", "The cost becomes non-convex"], "a": 0, "expl": "lambda = 0 gives plain linear regression; a huge lambda over-penalizes steepness, flattening the line into an underfit.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-043", "cat": "ml", "diff": 2, "q": "What can Lasso do that Ridge cannot?", "options": ["Handle multicollinearity", "Work without a lambda hyperparameter", "Shrink a coefficient all the way to ≈ 0, dropping the feature entirely", "Fit non-linear patterns"], "a": 2, "expl": "The L1 penalty can zero a coefficient out — automatic feature selection. Ridge only shrinks coefficients toward 0 and never quite reaches it.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-044", "cat": "ml", "diff": 2, "q": "Sum of squared errors = 100, slope = 3, lambda = 1. What is the Ridge cost?", "options": ["103", "109", "118", "100"], "a": 1, "expl": "Ridge adds lambda × slope² = 1 × 3² = 9, so cost = 100 + 9 = 109. Lasso would give 100 + 3 = 103.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-045", "cat": "ml", "diff": 1, "q": "Features are highly correlated (multicollinearity) and you want stable coefficients. What do you reach for?", "options": ["Lasso, to delete the correlated features", "Plain linear regression, it is unaffected", "Ridge — L2 is the standard answer for multicollinearity", "A bigger learning rate"], "a": 2, "expl": "Interview angle: Ridge for multicollinearity and stability; Lasso when you suspect useless features and want feature selection.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-046", "cat": "ml", "diff": 3, "q": "How do you choose the value of lambda?", "options": ["Gradient descent learns it automatically during training", "Always set lambda = 1", "It is a hyperparameter, picked via cross-validation", "Set lambda equal to the number of features"], "a": 2, "expl": "lambda is a hyperparameter, not a learned weight — try a range of values and let cross-validation pick the winner.", "remedy": "Notes + quiz: ../krish-ml-6h/06-ridge-lasso.html"}, {"id": "ml-047", "cat": "ml", "diff": 2, "q": "Despite its name, logistic regression is really used for...", "options": ["Regression with logistic constraints", "Clustering", "Classification — predicting discrete classes", "Dimensionality reduction"], "a": 2, "expl": "The name is historical. Logistic regression predicts categories: spam or not, churn or no churn.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-048", "cat": "ml", "diff": 1, "q": "Which function squashes any real number into the range (0, 1)?", "options": ["ReLU", "The sigmoid: g(z) = 1/(1+e^(−z))", "z squared", "The identity function"], "a": 1, "expl": "Big negative z → near 0, big positive z → near 1, and it never actually reaches 0 or 1.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-049", "cat": "ml", "diff": 2, "q": "Why is plain linear regression a poor choice for a 0/1 classification problem?", "options": ["It is too slow on big data", "Outliers drag the best-fit line, and outputs go below 0 or above 1 — invalid probabilities", "It cannot handle numeric features", "It always finds the global minimum"], "a": 1, "expl": "One outlier shifts the whole line, and a line happily predicts −0.3 or 1.4 — numbers that cannot be probabilities.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-050", "cat": "ml", "diff": 2, "q": "The model outputs h = 0.9 for an email. What does that mean?", "options": ["The model is 90% accurate", "90% probability that the class is 1", "The email is 10% spam", "The error is 0.9"], "a": 1, "expl": "h = g(θᵀx) is read as the probability that the class is 1 — here, a strong lean toward class 1.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-051", "cat": "ml", "diff": 1, "q": "What goes wrong if you use MSE on top of a sigmoid output?", "options": ["The cost becomes convex but slow to compute", "The cost becomes non-convex — local minima can trap gradient descent", "MSE outputs values above 1", "Nothing, MSE always works"], "a": 1, "expl": "Sigmoid + MSE gives a bumpy, non-convex surface; gradient descent can settle in a local minimum instead of the global one.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-052", "cat": "ml", "diff": 3, "q": "When does the model predict class 1?", "options": ["Whenever z is negative", "When g(z) ≥ 0.5, which is the same as z ≥ 0", "When h equals exactly 0", "When the cost is maximal"], "a": 1, "expl": "g(0) = 0.5, so the probability threshold 0.5 is the same boundary as the weighted sum z crossing 0.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-053", "cat": "ml", "diff": 2, "q": "What is g(0), the sigmoid evaluated at z = 0?", "options": ["0", "1", "0.5", "Undefined"], "a": 2, "expl": "g(0) = 1/(1 + e⁰) = 1/2 = 0.5 — exactly the decision boundary.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-054", "cat": "ml", "diff": 1, "q": "True class y = 1 and the model outputs h = 0.7. What is the log-loss cost?", "options": ["−log(0.3) ≈ 1.20", "−log(0.7) ≈ 0.36", "(1 − 0.7)² = 0.09", "0.7"], "a": 1, "expl": "For y = 1 the cost is −log(h) = −log(0.7) ≈ 0.36. The −log(0.3) branch applies when y = 0.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-055", "cat": "ml", "diff": 2, "q": "Interview check: why does log loss train better than MSE for logistic regression?", "options": ["Log loss is convex with a well-behaved gradient, so gradient descent reaches the global minimum", "Log loss needs fewer training examples", "MSE has no derivative", "Log loss removes the need for the sigmoid"], "a": 0, "expl": "Convexity is the whole story: one clean bowl, one global minimum, well-behaved gradients — unlike the bumpy MSE-on-sigmoid surface.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-056", "cat": "ml", "diff": 2, "q": "In z = θᵀx, what is z?", "options": ["The final probability", "The weighted sum of the input features using parameters θ", "The number of training examples", "The learning rate"], "a": 1, "expl": "z is the linear part — features weighted by θ — and the sigmoid then maps that z to a probability.", "remedy": "Notes + quiz: ../krish-ml-6h/07-logistic-regression.html"}, {"id": "ml-057", "cat": "ml", "diff": 1, "q": "Which loader brings in the dataset for this practical?", "options": ["load_boston() from sklearn.datasets", "pd.read_csv(boston.csv)", "load_diabetes()", "fetch_california_housing()"], "a": 0, "expl": "The video uses sklearn.datasets.load_boston, then builds the table with pd.DataFrame(data.data, columns=data.feature_names) and adds df[&#39;Price&#39;] = data.target.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-058", "cat": "ml", "diff": 3, "q": "How are X and y sliced from the DataFrame?", "options": ["X = df.iloc[:,:-1] (all but the last column), y = df.iloc[:,-1] (the Price column)", "X = all columns, y = all rows", "X = df.iloc[:,-1], y = df.iloc[:,:-1] — accidentally swapped", "Both come from data.feature_names"], "a": 0, "expl": "Features are every column except the last; the target is the last column, Price.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-059", "cat": "ml", "diff": 2, "q": "Why use cross_val_score with cv=5 instead of a single train_test_split?", "options": ["It trains 5 different algorithms and picks one", "It averages 5 different train/test folds, so one lucky split cannot fool you", "It creates 5x more training data", "It automatically removes outliers"], "a": 1, "expl": "Five folds means five different train/test evaluations averaged — no single lucky split can inflate your score.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-060", "cat": "ml", "diff": 1, "q": "The mean CV score is −37.1. What MSE does that correspond to?", "options": ["≈ 37.13", "≈ −37.13", "≈ 1376 (which is 37.1 squared)", "≈ 0.371"], "a": 0, "expl": "scikit-learn negates error metrics because it maximizes scores, so the MSE is the magnitude: ≈ 37.13.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-061", "cat": "ml", "diff": 2, "q": "With cv=5, how many times does cross_val_score fit the model?", "options": ["Once, on all the data", "5 times — one fit per fold", "10 times", "25 times"], "a": 1, "expl": "Each of the 5 folds takes one turn as the test set, so the model is fit 5 times and the 5 scores are averaged.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-062", "cat": "ml", "diff": 2, "q": "Why is the scoring string neg_mean_squared_error rather than mean_squared_error?", "options": ["Because MSE is negative by definition", "scikit-learn maximizes scores, so loss metrics are handed over negated", "A legacy typo kept for compatibility", "To keep the score positive"], "a": 1, "expl": "The negation is a scikit-learn convention: all scorers follow a higher-is-better contract, so errors come out negative.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-063", "cat": "ml", "diff": 1, "q": "Interview nugget: what happened to load_boston?", "options": ["Nothing — it is still the default regression dataset", "It was renamed to load_boston_v2", "It was removed from scikit-learn over ethical concerns; modern code uses alternative datasets", "It moved into the statsmodels library"], "a": 2, "expl": "The dataset was pulled from scikit-learn for ethical reasons. Knowing this signals you keep up with the libraries on your resume.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-064", "cat": "ml", "diff": 3, "q": "The model is trained. Which call produces price predictions for new data?", "options": ["model.score(new_data)", "model.predict(new_data)", "model.fit(new_data)", "cross_val_score(new_data)"], "a": 1, "expl": "predict() runs the fitted model on new feature rows and returns the predicted prices.", "remedy": "Notes + quiz: ../krish-ml-6h/08-linear-regression-practical.html"}, {"id": "ml-065", "cat": "ml", "diff": 2, "q": "What does GridSearchCV actually do in this practical?", "options": ["Performs feature selection automatically", "Tries every alpha in the param_grid with cross-validation and keeps the best one", "Trains a single model with alpha = 1", "Splits the data 33/67"], "a": 1, "expl": "It is a brute-force tuner: every grid value gets a full 5-fold CV evaluation under the chosen scoring metric.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-066", "cat": "ml", "diff": 1, "q": "In scikit-learn Ridge and Lasso, the theoretical lambda shows up under which name?", "options": ["lambda", "alpha", "reg", "penalty"], "a": 1, "expl": "Same concept, different label: scikit-learn calls the regularization strength alpha.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-067", "cat": "ml", "diff": 2, "q": "Which alpha won the grid search, and how much did the score improve?", "options": ["alpha = 1e-5, from −37 to −10", "alpha ≈ 100, from about −37 to about −29", "alpha = 1, from −29 back to −37", "alpha = 50, with no improvement"], "a": 1, "expl": "The largest grid value, alpha ≈ 100, won, lifting the CV score from about −37 to about −29.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-068", "cat": "ml", "diff": 2, "q": "Which attributes read the grid search results back?", "options": [".best_model and .best_loss", ".best_params_ and .best_score_", ".coef_ and .intercept_", ".grid_results and .cv_scores"], "a": 1, "expl": "best_params_ gives the winning hyperparameters (alpha ≈ 100 here); best_score_ gives its CV score.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-069", "cat": "ml", "diff": 1, "q": "On train_test_split(test_size=0.33), which model scored best?", "options": ["Linear regression at ≈ −25.8", "Ridge with alpha = 100 at ≈ −25.47", "Lasso with alpha = 1 at ≈ −35", "All three tied"], "a": 1, "expl": "Remember: closer to 0 is better. Ridge (−25.47) edges linear (−25.8); Lasso at alpha = 1 lags at ≈ −35.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-070", "cat": "ml", "diff": 3, "q": "The R² score lands at ≈ 0.67-0.68. What does that tell you?", "options": ["The model classifies 67% of rows correctly", "The model explains roughly 67-68% of the variance in the target", "67% of predictions are exactly right", "The MSE is 0.67"], "a": 1, "expl": "R² near 0.67 means the linear model captures about two-thirds of the variance — decent, but clearly capped.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-071", "cat": "ml", "diff": 2, "q": "Video takeaway: why stop squeezing these linear models for score?", "options": ["Linear regression cannot handle large datasets", "A straight line caps out — meaningfully better scores need non-linear models such as XGBoost", "Ridge and Lasso are deprecated", "The Boston dataset is too small for Ridge"], "a": 1, "expl": "Tuning Ridge/Lasso further yields marginal gains; the video points to non-linear models like XGBoost for real improvements.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-072", "cat": "ml", "diff": 1, "q": "Interview check: which four ingredients go into a GridSearchCV call?", "options": ["estimator, param_grid, scoring, cv", "X, y, test_size, random_state", "alpha, lambda, beta, gamma", "model, optimizer, loss, epochs"], "a": 0, "expl": "GridSearchCV(estimator, param_grid, scoring, cv) — here Ridge, the alpha grid, neg_mean_squared_error, cv=5.", "remedy": "Notes + quiz: ../krish-ml-6h/09-ridge-lasso-practical.html"}, {"id": "ml-073", "cat": "ml", "diff": 2, "q": "Naive Bayes is built directly on which mathematical foundation?", "options": ["Fitting a line through all points by gradient descent", "Conditional probability and Bayes theorem", "Eigendecomposition of the feature covariance matrix", "Maximizing the margin between classes"], "a": 1, "expl": "Everything in this section — dice, marbles, tennis — is conditional probability rearranged through Bayes theorem.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-074", "cat": "ml", "diff": 2, "q": "Two fair dice are rolled. For independent events A and B, P(A∩B) equals:", "options": ["P(A) + P(B)", "P(A) · P(B|A)", "P(A) · P(B)", "P(B|A) · P(A) / P(B)"], "a": 2, "expl": "Dice rolls do not influence each other, so the joint is the product of the marginals: 1/6 × 1/6 = 1/36.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-075", "cat": "ml", "diff": 1, "q": "Drawing two marbles from a bag WITHOUT replacement is an example of:", "options": ["Dependent events: P(A∩B) = P(A) · P(B|A)", "Independent events: P(A∩B) = P(A) · P(B)", "Mutually exclusive events: P(A∩B) = 0", "Uncomputable probability without a simulation"], "a": 0, "expl": "The first draw changes what is left in the bag, so the second factor is a conditional probability.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-076", "cat": "ml", "diff": 3, "q": "In P(y|x1,…,xn) ∝ P(y) · Π P(xi|y), why is the denominator dropped?", "options": ["It is always equal to 1", "It cannot be estimated from training data", "It is identical for every class, so it never changes which class wins", "Naive Bayes never outputs probabilities"], "a": 2, "expl": "We only compare scores across classes; a constant positive factor does not affect the ranking, so the evidence term is skipped.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-077", "cat": "ml", "diff": 2, "q": "For (Sunny, Hot) the unnormalized scores are Yes ≈ 0.31 and No ≈ 0.857. After normalization:", "options": ["Yes ≈ 73% vs No ≈ 27% → predict Yes", "Yes ≈ 27% vs No ≈ 73% → predict No", "Predict Yes — only 0.31 is a valid probability", "Undecidable because the denominator was dropped"], "a": 1, "expl": "0.31/(0.31+0.857) ≈ 27% and 0.857/(0.31+0.857) ≈ 73%; the larger posterior wins → No.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-078", "cat": "ml", "diff": 1, "q": "Homework case (Overcast, Mild): the Outlook count table says Overcast has 4-yes / 0-no. The prediction:", "options": ["Depends only on the temperature value Mild", "No — a zero count means that class is the most likely", "The model refuses to answer when a count is 0", "Yes — the No score collapses to 0 because P(Overcast|No) = 0/5"], "a": 3, "expl": "One zero factor makes the whole No product 0, so Yes wins regardless of the remaining features.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-079", "cat": "ml", "diff": 2, "q": "In Naive Bayes, the word naive refers to:", "options": ["It only works for two classes", "It never uses the prior P(y)", "The assumption that features are independent of each other given the class", "The assumption that all classes are equally likely"], "a": 2, "expl": "P(y) · Π P(xi|y) multiplies per-feature likelihoods as if features were independent once the class is known.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-080", "cat": "ml", "diff": 2, "q": "Interview classic: the independence assumption is almost never true, yet Naive Bayes is still widely used because:", "options": ["It makes zero errors on text data", "Independence violations cancel out in every dataset", "Deep learning made accuracy irrelevant", "It still performs surprisingly well on text/spam, is fast, and is the go-to baseline"], "a": 3, "expl": "Real features are correlated, but the relative ranking of class scores is usually still right for bag-of-words problems — fast, simple, effective.", "remedy": "Notes + quiz: ../krish-ml-6h/10-naive-bayes.html"}, {"id": "ml-081", "cat": "ml", "diff": 1, "q": "KNN assigns a class label to a new point by:", "options": ["Fitting a line through all training points", "Computing a sigmoid probability", "Majority vote among its k closest training points", "Using only the single nearest neighbor, whatever k is"], "a": 2, "expl": "Video example with k=5: 3 red vs 2 white neighbors → the new point is labeled red.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-082", "cat": "ml", "diff": 3, "q": "KNN applied to REGRESSION predicts:", "options": ["The average of the target values of its k nearest neighbors", "The majority vote of the neighbors", "The median of the entire dataset", "A polynomial extrapolation from the neighbors"], "a": 0, "expl": "Same neighbor search, continuous output: average the neighbors instead of voting.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-083", "cat": "ml", "diff": 2, "q": "The Manhattan distance between (1,2) and (4,6) is:", "options": ["√((4−1)² + (6−2)²) = 5", "|4−1| + |6−2| = 7", "3", "10"], "a": 1, "expl": "Manhattan = city-block distance: sum of absolute coordinate differences. Euclidean would give 5.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-084", "cat": "ml", "diff": 1, "q": "How does the video recommend choosing k?", "options": ["Always use k = 1", "Always use k = number of classes", "Set k equal to the number of features", "Try k = 1 up to about 50 and keep the k with the lowest error"], "a": 3, "expl": "k is a hyperparameter: sweep values, compare the error for each, keep the winner.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-085", "cat": "ml", "diff": 2, "q": "If k is too small (say k = 1):", "options": ["The decision boundary becomes too smooth and underfits", "Single noisy points decide, so outliers can flip labels", "Distance stops mattering", "Predictions become the dataset average"], "a": 1, "expl": "With k = 1 the nearest single point decides — noise and outliers win. Classic overfitting.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-086", "cat": "ml", "diff": 2, "q": "Why must data be standardized or normalized before KNN?", "options": ["KNN cannot handle negative numbers", "Standardization automatically removes outliers", "Distances add features of different scales, so the largest-scale feature would dominate", "k must equal the number of standardized features"], "a": 2, "expl": "Salary in thousands vs age in years: without scaling, salary alone decides who the neighbors are.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-087", "cat": "ml", "diff": 1, "q": "KNN is called a LAZY learner because:", "options": ["It never achieves good accuracy", "It only works on small datasets", "It skips the majority vote", "There is no real training phase — the work happens at prediction time"], "a": 3, "expl": "KNN just stores the data and computes distances when a prediction is requested: training cost near zero, inference cost high.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-088", "cat": "ml", "diff": 3, "q": "Interview rapid-fire — pick the fully correct line:", "options": ["Outliers: no impact · Normalization: needed · Trees/Forests: need it too", "Outliers: impact KNN · Normalization: needed · Trees/Forests: do NOT need it", "Outliers: impact KNN · Normalization: not needed · Trees: need it", "Outliers: no impact · Normalization: not needed · Trees: need it"], "a": 1, "expl": "KNN is distance-based → outlier-sensitive and scale-sensitive. Trees compare values against thresholds → scale-invariant.", "remedy": "Notes + quiz: ../krish-ml-6h/11-knn.html"}, {"id": "ml-089", "cat": "ml", "diff": 2, "q": "In a decision tree, the FINAL predicted output is produced at the:", "options": ["Root node", "Internal nodes", "Leaf nodes", "Branch edges"], "a": 2, "expl": "The root asks the first question, internal nodes ask more, and the leaves hold the final class output.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-090", "cat": "ml", "diff": 1, "q": "A decision tree is best described as:", "options": ["A weighted sum of all input features", "Learned nested IF-ELSE conditions", "A distance calculation in feature space", "A chain of matrix multiplications"], "a": 1, "expl": "Each root-to-leaf path is literally one if-else rule; the algorithm learns which questions to ask and in what order.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-091", "cat": "ml", "diff": 2, "q": "After the tennis data (root 9-yes / 5-no) splits on Outlook, which node is PURE?", "options": ["The root: 9-yes / 5-no", "Sunny: 2-yes / 3-no", "Rain: 3-yes / 2-no", "Overcast: 4-yes / 0-no"], "a": 3, "expl": "Pure = all rows belong to one class. The overcast branch stops immediately with leaf output Yes.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-092", "cat": "ml", "diff": 2, "q": "The entropy of a PURE node is:", "options": ["1", "0.5", "0", "Undefined"], "a": 2, "expl": "H = −p·log₂(p) − (1−p)·log₂(1−p) gives 0 at p=0 or p=1; the maximum of 1 occurs at 50/50.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-093", "cat": "ml", "diff": 1, "q": "Root entropy H(S) = 0.94 and a split produces children with weighted entropy ≈ 0.43. The information gain is about:", "options": ["0.487", "1.37", "0.041", "0.51"], "a": 3, "expl": "Gain = 0.94 − 0.43 ≈ 0.51 — the strong feature from the video. The weak feature1 only reached ≈ 0.041 (children still ≈ 0.89 impure).", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-094", "cat": "ml", "diff": 3, "q": "Why does scikit-learn use Gini as its default criterion instead of entropy?", "options": ["Gini always finds different, better splits", "No logarithm is needed, so it is computationally faster with very similar splits", "Entropy is undefined for binary problems", "Gini allows unlimited tree depth"], "a": 1, "expl": "Gini = 1 − Σpᵢ² needs no log; in practice both criteria pick nearly the same splits.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-095", "cat": "ml", "diff": 2, "q": "The maximum Gini impurity for a BINARY classification node is:", "options": ["0.5", "1", "0", "2"], "a": 0, "expl": "At 50/50: 1 − (0.5² + 0.5²) = 0.5. Entropy maxes at 1, Gini at 0.5.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-096", "cat": "ml", "diff": 1, "q": "For a CONTINUOUS feature, candidate splits are found by:", "options": ["Splitting at the mean value only", "Splitting at the median value only", "Sorting the values, testing thresholds between consecutive points, and computing the gain of each", "Sampling random thresholds until one looks good"], "a": 2, "expl": "Every candidate threshold gets its own information-gain score; the best one becomes the IF-ELSE test (e.g. x < 6.5).", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-097", "cat": "ml", "diff": 2, "q": "The video shows a split separating 47 samples from just 1. Cutting that branch afterwards is called:", "options": ["A perfect pure split worth keeping", "Pre-pruning with max_depth", "A required class-balancing step", "Post-pruning: grow the full tree, then remove branches that only memorize single rows"], "a": 3, "expl": "Cutting after growing = post-pruning. Pre-pruning limits growth upfront (max_depth, min_samples_leaf — tuned with GridSearchCV).", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-098", "cat": "ml", "diff": 2, "q": "Interview rapid-fire: which models need feature scaling?", "options": ["KNN: yes · Decision Tree: yes", "KNN: no · Decision Tree: yes", "KNN: yes · Decision Tree: no", "KNN: no · Decision Tree: no"], "a": 2, "expl": "KNN sums distances across features → scale-sensitive. Trees compare values against thresholds → scale-invariant.", "remedy": "Notes + quiz: ../krish-ml-6h/12-decision-tree-classification.html"}, {"id": "ml-099", "cat": "ml", "diff": 1, "q": "The main change from DT classification to DT regression:", "options": ["Leaves store the MEAN of the targets instead of the majority class", "Regression trees use entropy computed on continuous targets", "Regression trees have no root node", "Classification trees need scaling but regression trees do not"], "a": 0, "expl": "Same structure; the output and split criterion change — leaf means + MSE reduction instead of class votes + entropy/Gini.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-100", "cat": "ml", "diff": 3, "q": "Training outputs 20, 24, 26, 28, 30 all reach the root. The root predicts:", "options": ["26", "25.6", "20", "30"], "a": 1, "expl": "The root stores the mean of ALL its targets: 128/5 = 25.6.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-101", "cat": "ml", "diff": 2, "q": "A split sends {20, 24, 26} to node1 and {28, 30} to node2. Node1 stores:", "options": ["25.6", "29", "23.33", "24"], "a": 2, "expl": "(20+24+26)/3 = 70/3 ≈ 23.33. Node2 stores (28+30)/2 = 29.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-102", "cat": "ml", "diff": 1, "q": "Split quality in regression trees is measured by:", "options": ["Information gain using entropy", "Gini impurity reduction", "Size of the majority vote", "Reduction in MSE (or MAE)"], "a": 3, "expl": "Entropy/Gini need class labels; regression trees maximize the drop in squared (or absolute) error.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-103", "cat": "ml", "diff": 2, "q": "A new point lands in a leaf whose training targets were {28, 30}. Its prediction:", "options": ["28", "25.6", "30", "29"], "a": 3, "expl": "Prediction = mean of the leaf it falls into: (28+30)/2 = 29. The model is piecewise-constant.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-104", "cat": "ml", "diff": 2, "q": "What happens as the regression tree is grown deeper and deeper?", "options": ["Within-node MSE keeps dropping toward 0, and single-row leaves just memorize training data", "MSE increases at every split", "Predictions inside the same leaf keep changing", "The mean is eventually replaced by the median"], "a": 0, "expl": "Deeper splits group similar targets; a 1-row leaf has training MSE 0 — textbook overfitting, which is why we prune.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-105", "cat": "ml", "diff": 1, "q": "Which statement about feature scaling is correct?", "options": ["DT regression needs standardization, just like KNN", "No scaling needed — threshold splits are scale-invariant", "Only the target column must be standardized", "Scaling changes the stored leaf means"], "a": 1, "expl": "Comparing a feature against a threshold ignores units — a key tree-family advantage over distance-based KNN.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-106", "cat": "ml", "diff": 3, "q": "Two different points land in the SAME leaf of a regression tree. Their predictions are:", "options": ["Different — scaled by their feature values", "Different — one gets the mean, the other the median", "Identical — the leaf outputs one constant mean", "Undefined until the model is retrained"], "a": 2, "expl": "Each leaf stores exactly one value (the mean of its training targets), so output is constant within a leaf.", "remedy": "Notes + quiz: ../krish-ml-6h/13-decision-tree-regression.html"}, {"id": "ml-107", "cat": "ml", "diff": 2, "q": "What is the DEFAULT criterion used by sklearn DecisionTreeClassifier() when you pass no arguments?", "options": ["entropy", "gini", "mean_squared_error", "it depends on the dataset"], "a": 1, "expl": "No arguments means criterion=gini. Entropy is the other supported option and must be set explicitly.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-108", "cat": "ml", "diff": 1, "q": "Which values are valid options for the criterion parameter of DecisionTreeClassifier?", "options": ["gini and entropy", "gini and mean_squared_error", "entropy and f1_score", "squared_error and absolute_error"], "a": 0, "expl": "The video names exactly two options: gini and entropy.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-109", "cat": "ml", "diff": 2, "q": "What are the two possible values of the splitter parameter?", "options": ["auto and full", "greedy and lazy", "best and random", "gini and entropy"], "a": 2, "expl": "splitter=best (the default) takes the best split found at each node; splitter=random takes a random one.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-110", "cat": "ml", "diff": 2, "q": "Which set of parameters limits tree growth (pre-pruning), as shown in the video?", "options": ["n_estimators, learning_rate, max_features", "max_depth, min_samples_leaf, max_features", "max_depth, n_neighbors, C", "min_samples_leaf, gamma, kernel"], "a": 1, "expl": "max_depth, min_samples_leaf and max_features cap how far the tree grows. n_estimators and learning_rate belong to ensembles; C, gamma, kernel to SVMs; n_neighbors to KNN.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-111", "cat": "ml", "diff": 1, "q": "The fitted tree shows one branch with 47 samples and another with just 1. What is the correct interpretation and action?", "options": ["The tree is underfitting — grow it deeper", "The 1-sample branch is memorized noise; cut that branch back (post-pruning)", "A 47-vs-1 split means the dataset must be rebalanced with SMOTE", "The 1-sample branch holds the most important rule in the tree"], "a": 1, "expl": "A leaf holding a single sample is the tree memorizing one odd row. Cutting already-grown branches back is post-pruning.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-112", "cat": "ml", "diff": 3, "q": "How does the video visually inspect the trained tree to spot silly branches?", "options": ["model.print_tree(depth=50)", "a seaborn heatmap of the confusion matrix", "plot_tree(model, figsize=(15,10), filled=True)", "only a feature_importances_ bar chart"], "a": 2, "expl": "plot_tree with filled=True colours nodes by majority class, so tiny impure leaves stand out immediately.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-113", "cat": "ml", "diff": 2, "q": "You call model.predict(X_test) but forgot to run model.fit(X_train, y_train) first. What happens?", "options": ["sklearn raises a NotFittedError", "sklearn fits silently and then returns predictions", "you get predictions that are all zeros", "you get an accuracy of 0 but no exception"], "a": 0, "expl": "predict on an unfitted estimator raises NotFittedError — fit must always run first.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-114", "cat": "ml", "diff": 1, "q": "A fully grown (unpruned) decision tree is scored on both train and test sets. Which pattern do you expect?", "options": ["Low accuracy on both train and test", "High test accuracy but low train accuracy", "Identical accuracy on train and test", "Very high train accuracy but lower test accuracy — overfitting"], "a": 3, "expl": "Unlimited growth memorizes the training set: train score very high, test score drops. The gap is the overfitting.", "remedy": "Notes + quiz: ../krish-ml-6h/14-decision-tree-practical.html"}, {"id": "ml-115", "cat": "ml", "diff": 2, "q": "In ML, what does the term ENSEMBLE mean?", "options": ["Combining multiple models so their combined prediction beats any single one", "A single very deep decision tree", "A technique to normalize features before training", "Storing many copies of one trained model as backups"], "a": 0, "expl": "Ensemble literally means combining several models into one prediction.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-116", "cat": "ml", "diff": 2, "q": "Bagging builds its data subsets using which sampling scheme?", "options": ["Random row sampling WITHOUT replacement", "Random row sampling WITH replacement (bootstrap)", "Sampling only the rows that have missing values", "Random column sampling only"], "a": 1, "expl": "Bootstrap = random rows sampled WITH replacement, so a row can repeat inside one subset.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-117", "cat": "ml", "diff": 1, "q": "In bagging, the member models are trained...", "options": ["sequentially, each fixing the errors of the previous one", "in parallel, independently of each other", "one single model at a time on the full data", "only after the test score is known"], "a": 1, "expl": "Bagging members are independent of each other, so they train in parallel. Sequential training is the signature of boosting.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-118", "cat": "ml", "diff": 3, "q": "How are individual bagged-model predictions combined for CLASSIFICATION?", "options": ["By averaging the predicted probabilities", "By taking the maximum probability across models", "By majority vote across the models", "By picking the model with the lowest training loss"], "a": 2, "expl": "Classification aggregates by majority vote; the mean is used for regression.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-119", "cat": "ml", "diff": 2, "q": "How are individual bagged-model predictions combined for REGRESSION?", "options": ["Mean of all model outputs", "Majority vote", "Median of the two worst models", "Concatenation of the outputs"], "a": 0, "expl": "Regression averages the predictions; voting is for classes.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-120", "cat": "ml", "diff": 1, "q": "Why does the video suggest using around 100-200 models in a bagging ensemble?", "options": ["More models always push accuracy to 100%", "With that many voters, a tied vote becomes practically impossible", "Each model must see the data exactly once in total", "sklearn refuses to aggregate fewer than 100 models"], "a": 1, "expl": "A big committee makes tied votes practically impossible and keeps the aggregated prediction stable.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-121", "cat": "ml", "diff": 2, "q": "What defines BOOSTING, as opposed to bagging?", "options": ["Models trained in parallel on bootstrap samples", "Models trained sequentially, each new weak learner fixing the errors of the previous ones", "Models that all share the same weights", "Training one giant model with more layers"], "a": 1, "expl": "Boosting is sequential: each new weak learner targets the mistakes of what came before.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-122", "cat": "ml", "diff": 2, "q": "The teacher analogy — one teacher each for physics, chemistry, maths, geography — illustrates which idea?", "options": ["Every model must see every subject", "Weak learners chained so each specializes on what the previous ones got wrong, forming a strong learner", "Teachers should be replaced by decision trees", "Subjects must be normalized before teaching"], "a": 1, "expl": "Each specialist covers what the others missed — the boosting pattern that turns weak learners into a strong learner.", "remedy": "Notes + quiz: ../krish-ml-6h/15-ensemble-bagging-boosting.html"}, {"id": "ml-123", "cat": "ml", "diff": 1, "q": "What is a random forest, in one line?", "options": ["One very deep decision tree with a tuned depth", "Bagging applied with decision trees as the base models — many trees form a forest", "A neural network shaped like a tree", "KNN run on bootstrapped samples"], "a": 1, "expl": "Random forest = the bagging recipe with decision trees as the members.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-124", "cat": "ml", "diff": 3, "q": "Which TWO samplings does random forest apply to build each tree?", "options": ["Row sampling and feature sampling", "Row sampling and label sampling", "Feature sampling and learning-rate sampling", "Epoch sampling and batch sampling"], "a": 0, "expl": "Each tree sees a bootstrap sample of the rows AND a random subset of the features.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-125", "cat": "ml", "diff": 2, "q": "Why does each tree only get a random subset of the features?", "options": ["To save disk space on the dataset", "Because some features are always encrypted", "To make the trees different from each other (decorrelated), so their averaged errors cancel", "Because trees cannot handle more than 10 columns"], "a": 2, "expl": "Feature sampling decorrelates the trees — identical trees would repeat identical mistakes, and averaging them would do nothing.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-126", "cat": "ml", "diff": 1, "q": "A single fully grown decision tree has which bias-variance profile?", "options": ["High bias, low variance", "Low bias, high variance", "High bias, high variance", "Low bias, low variance"], "a": 1, "expl": "It hugs the training data (low bias) but is very sensitive to changes in the data (high variance) — that is overfitting.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-127", "cat": "ml", "diff": 2, "q": "Averaging many decorrelated trees mainly reduces which term of the error decomposition?", "options": ["The bias term", "The variance term", "The irreducible noise", "The learning rate"], "a": 1, "expl": "Bagging-style averaging keeps bias roughly the same and slashes the variance term.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-128", "cat": "ml", "diff": 2, "q": "How does a random forest make its final CLASSIFICATION prediction?", "options": ["The deepest tree decides", "Every tree votes and the majority wins", "The first tree that was trained decides", "It sums all class probabilities to 100"], "a": 1, "expl": "Each tree casts a vote and the majority vote wins. Regression averages the outputs instead.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-129", "cat": "ml", "diff": 1, "q": "Does a random forest need normalization or standardization of features?", "options": ["Yes, z-score every column first", "Yes, but only the numeric columns", "No — tree splits compare values against thresholds, which are scale-invariant", "Only when the dataset has more than 1000 rows"], "a": 2, "expl": "Scaling a column does not change where threshold splits happen, so the forest is scale-invariant.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-130", "cat": "ml", "diff": 3, "q": "Does KNN need normalization/standardization, and why?", "options": ["No — KNN is also tree-based", "Yes — KNN uses distances, so a large-scale feature would dominate them", "Only for categorical features", "No — sklearn scales the data automatically"], "a": 1, "expl": "Distance-based models are scale-sensitive: without scaling, the widest-range feature decides every distance.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-131", "cat": "ml", "diff": 2, "q": "How are random forest and KNN each impacted by outliers?", "options": ["Both are highly sensitive to outliers", "RF: not much (threshold splits are robust) · KNN: yes (distances get distorted)", "RF: heavily impacted · KNN: not at all", "Neither is affected in any way"], "a": 1, "expl": "A threshold split barely moves when one extreme value appears; a KNN distance does not have that protection.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-132", "cat": "ml", "diff": 1, "q": "Can random forest be used for both classification and regression?", "options": ["No, classification only", "No, regression only", "Yes — majority vote for classification, averaging for regression", "Only with a separate paid library"], "a": 2, "expl": "The same forest supports both tasks: vote for classes, average for numbers.", "remedy": "Notes + quiz: ../krish-ml-6h/16-random-forest.html"}, {"id": "ml-133", "cat": "ml", "diff": 2, "q": "What exactly is a STUMP in AdaBoost?", "options": ["A decision tree limited to depth 1 — one feature, one split", "A decision tree with unlimited depth", "The root node of a random forest", "A tree ensemble with 100 members"], "a": 0, "expl": "A stump = a depth-1 tree = a weak learner. AdaBoost chains many of them sequentially.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-134", "cat": "ml", "diff": 2, "q": "How are sample weights initialized at the start of AdaBoost?", "options": ["Random values between 0 and 1", "All equal to 1/n for n samples", "All equal to 1", "Proportional to the target value of each sample"], "a": 1, "expl": "Step 1: every sample starts equal — weight = 1/n.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-135", "cat": "ml", "diff": 1, "q": "The Total Error (TE) of a stump is...", "options": ["The number of misclassified samples divided by the number of features", "The sum of the weights of the misclassified samples, always between 0 and 1", "The training accuracy of the stump", "The sum of all weights before normalization"], "a": 1, "expl": "TE adds up the weights of the samples the stump got wrong — so TE always lies between 0 and 1.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-136", "cat": "ml", "diff": 3, "q": "A stump has Total Error TE = 1/7. Compute its performance α = ½·ln((1−TE)/TE).", "options": ["≈ 0.895", "≈ 0.349", "≈ 0.500", "≈ 1.792"], "a": 0, "expl": "α = ½·ln((6/7)/(1/7)) = ½·ln(6) ≈ 0.5 × 1.792 ≈ 0.895 — the worked example from the video.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-137", "cat": "ml", "diff": 2, "q": "A correctly classified sample starts with weight 1/7 and the stump has α ≈ 0.895. Its updated weight is approximately...", "options": ["0.349 — weights of correct samples grow", "0.05 — multiplied by e^(−α), correct samples shrink", "1 — correct samples keep full weight", "0.895 — the weight becomes α"], "a": 1, "expl": "Correct: w × e^(−α) = 1/7 × e^(−0.895) ≈ 0.05. Misclassified samples grow instead (≈ 0.349).", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-138", "cat": "ml", "diff": 1, "q": "What happens to the α of a stump whose Total Error is greater than 0.5?", "options": ["α becomes negative — the stump is worse than a coin flip, so effectively flip its predictions", "α becomes 1 by definition", "α becomes infinite", "Training stops immediately"], "a": 0, "expl": "TE > 0.5 makes (1−TE)/TE less than 1, so the log is negative: the vote counts against the stump.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-139", "cat": "ml", "diff": 2, "q": "A stump achieves TE = 0 on the data. What is its α?", "options": ["α = 0", "α = 0.5", "α → ∞ — a perfect stump gets infinite say", "α = −1"], "a": 2, "expl": "α = ½·ln((1−0)/0) divides by zero, so α → infinity: the perfect stump dominates the vote.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-140", "cat": "ml", "diff": 2, "q": "Why does AdaBoost create weight-proportional BUCKETS before resampling the data?", "options": ["To store model checkpoints", "So redraws with replacement pick previously misclassified points more often — the next stump focuses on them", "To sort features by importance", "To convert continuous features into categories"], "a": 1, "expl": "Bigger weight = bigger bucket = higher chance of being drawn, so the next stump trains on more of the hard points.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-141", "cat": "ml", "diff": 1, "q": "How does a trained AdaBoost model make its FINAL prediction?", "options": ["Only the first stump decides", "Only the stump with the lowest TE decides", "A weighted vote of ALL stumps — sum of α per class (regression: weighted average)", "The average of all stump depths"], "a": 2, "expl": "Every stump votes, weighted by its own α; the class with the biggest α-sum wins.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-142", "cat": "ml", "diff": 3, "q": "Interview question: why does AdaBoost keep ALL stumps instead of only the best-performing one?", "options": ["Because sklearn does not allow deleting stumps", "Because each vote is weighted by its α and the stumps specialize on different hard regions — dropping one loses the region it mastered", "Because more stumps always guarantee TE = 0", "Because the best stump alone would already be a strong learner"], "a": 1, "expl": "Each stump covers the hard region it was resampled to learn; the α-weighted vote of all of them is what makes the weak ensemble strong.", "remedy": "Notes + quiz: ../krish-ml-6h/17-adaboost-boosting.html"}, {"id": "ml-143", "cat": "ml", "diff": 2, "q": "K-Means is best described as which type of learning?", "options": ["Supervised classification — it predicts a labeled class", "Unsupervised — it finds groups in data with no output labels", "Supervised regression — it predicts a continuous value", "Reinforcement learning — it learns from rewards"], "a": 1, "expl": "There are no output labels in the data. The goal is to group similar points into K clusters, so this is unsupervised learning.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-144", "cat": "ml", "diff": 1, "q": "What does k-means++ initialization do differently from plain random initialization?", "options": ["It picks K automatically using the elbow method", "It normalizes all features before clustering", "It assigns every point to a random cluster first", "It places the initial centroids far apart from each other"], "a": 3, "expl": "k-means++ spreads the starting centroids far apart, which gives better, more stable clusters than random placement.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-145", "cat": "ml", "diff": 2, "q": "In the assignment step, each point is joined to its nearest centroid using which distance?", "options": ["Cosine similarity only", "Euclidean distance", "Manhattan distance only", "Hamming distance"], "a": 1, "expl": "Every point is assigned to the nearest centroid by Euclidean distance; then each centroid is recomputed as the mean of its points.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-146", "cat": "ml", "diff": 2, "q": "After all points are assigned, how is each centroid updated?", "options": ["It moves to the mean of the points assigned to it", "It stays fixed until convergence is declared", "It moves to the point farthest from the cluster", "It is re-initialized at a random data point"], "a": 0, "expl": "Steps 3-4 repeat: assign points to the nearest centroid, recompute each centroid as the mean of its assigned points, until assignments stop changing.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-147", "cat": "ml", "diff": 1, "q": "What does WCSS stand for?", "options": ["Weighted Centroid Standard Score", "Within-Class Sample Size", "Within-Cluster Sum of Squares", "Ward Cluster Selection Scheme"], "a": 2, "expl": "WCSS is the sum of squared distances from each point to its own centroid — lower means tighter clusters.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-148", "cat": "ml", "diff": 3, "q": "On a WCSS vs K plot, where does the elbow method tell you to pick K?", "options": ["At the abrupt change, the bend of the curve", "At the very end of the curve where WCSS is lowest", "At the K with the highest WCSS", "Wherever the curve becomes perfectly flat at zero"], "a": 0, "expl": "WCSS always falls as K grows, so the global minimum is meaningless — you pick the K at the bend, where adding clusters stops helping much.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-149", "cat": "ml", "diff": 2, "q": "What is a realistic risk of choosing K much too large?", "options": ["Euclidean distance stops working", "Clusters get so fine-grained they stop being useful segments", "The algorithm becomes supervised", "Centroids can never be computed"], "a": 1, "expl": "A too-large K slices the data into tiny fragments. WCSS keeps dropping, but the segments no longer map to real customer groups you can market to.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-150", "cat": "ml", "diff": 1, "q": "Interview: a teammate has 1M rows to cluster. Why reach for K-means over hierarchical clustering?", "options": ["Hierarchical clustering cannot run on numeric data", "K-means needs no K, hierarchical does", "K-means guarantees the globally optimal clustering", "K-means is faster on large datasets; hierarchical merging is too time-consuming at scale"], "a": 3, "expl": "K-means is the speed pick on large data. Watch the trap in option 2 — it is exactly backwards: K-means requires K up front.", "remedy": "Notes + quiz: ../krish-ml-6h/18-kmeans.html"}, {"id": "ml-151", "cat": "ml", "diff": 2, "q": "Agglomerative hierarchical clustering builds clusters in which direction?", "options": ["Top-down — one big cluster splits repeatedly", "Bottom-up — every point starts as its own cluster and pairs merge", "Left to right across the feature columns", "Random restarts from many seeds"], "a": 1, "expl": "Agglomerative means bottom-up: begin from n single-point clusters and repeatedly merge the two closest clusters.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-152", "cat": "ml", "diff": 2, "q": "With n data points, how many clusters exist at the very start?", "options": ["1", "K", "log2(n)", "n — one cluster per point"], "a": 3, "expl": "Every point begins as its own cluster, so n points give n clusters; each merge reduces the count by one.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-153", "cat": "ml", "diff": 1, "q": "What does a dendrogram record?", "options": ["The WCSS value for each K", "The full history of which clusters merged and at what distances", "The silhouette score of each point", "The coordinates of the final centroids"], "a": 1, "expl": "A dendrogram is the merge history drawn as a tree — each horizontal join is one merge, and its height shows how far apart the merged clusters were.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-154", "cat": "ml", "diff": 3, "q": "To choose the number of clusters, where do you cut the dendrogram?", "options": ["Across the longest vertical line that no horizontal line crosses", "Across the tallest horizontal line", "At the root, always leaving one cluster", "Wherever the leaf count equals ten"], "a": 0, "expl": "Find the longest vertical line with no horizontal line crossing it and cut there — that un-crossed stretch marks the most natural separation.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-155", "cat": "ml", "diff": 2, "q": "After making that cut, the number of clusters equals…", "options": ["The number of leaves minus one", "The height of the tallest merge", "The number of vertical lines the cut crosses", "The number of horizontal lines in the whole tree"], "a": 2, "expl": "Count the vertical lines crossed by the horizontal cut — that count is your number of clusters.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-156", "cat": "ml", "diff": 1, "q": "What is the headline advantage of hierarchical clustering over K-means?", "options": ["It always runs faster", "It needs no distance measure", "It handles unlimited data sizes", "You do not need to pre-choose the number of clusters"], "a": 3, "expl": "K-means demands K up front; the dendrogram lets hierarchical clustering reveal a natural K instead.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-157", "cat": "ml", "diff": 2, "q": "Why is hierarchical clustering typically used on smaller datasets?", "options": ["It is more time-consuming than K-means on big data", "It cannot compute distances on big data", "It requires labels, which big data lacks", "The dendrogram turns into a circle"], "a": 0, "expl": "The merging gets expensive as data grows, so K-means is preferred for speed on large datasets.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-158", "cat": "ml", "diff": 2, "q": "Interview: 500 rows to segment, and nobody knows K. What do you propose?", "options": ["Insist on K-means with K=10", "Collect labels first — clustering is impossible without them", "Try agglomerative clustering and read K off the dendrogram — small data is exactly its use case", "Refuse — hierarchical clustering has no way to choose K"], "a": 2, "expl": "Small data plus unknown K is the sweet spot for hierarchical clustering: no pre-chosen K, and the dendrogram justifies the cut.", "remedy": "Notes + quiz: ../krish-ml-6h/19-hierarchical-clustering.html"}, {"id": "ml-159", "cat": "ml", "diff": 1, "q": "The silhouette score is useful because it validates clustering…", "options": ["Using the target variable", "Only for supervised models", "Without needing any labels", "Only when K equals 2"], "a": 2, "expl": "It measures cohesion vs separation from the data itself — no ground-truth labels required, which is exactly what unsupervised clustering needs.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-160", "cat": "ml", "diff": 3, "q": "For a point i, what is a(i)?", "options": ["The average distance to the other points in its own cluster", "The average distance to the nearest other cluster", "The distance to the overall dataset centroid", "The number of points within epsilon"], "a": 0, "expl": "a(i) is cohesion — how snugly the point sits with the rest of its own cluster.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-161", "cat": "ml", "diff": 2, "q": "For a point i, what is b(i)?", "options": ["The average distance within its own cluster", "The average distance to the points in the nearest other cluster", "The maximum distance in the dataset", "The within-cluster sum of squares"], "a": 1, "expl": "b(i) is separation — how far the point is from the best alternative (nearest other) cluster.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-162", "cat": "ml", "diff": 1, "q": "A point with a NEGATIVE silhouette score means…", "options": ["It sits exactly on a boundary between two clusters", "It is a perfect core point", "The dataset must be re-normalized", "It is probably assigned to the wrong cluster"], "a": 3, "expl": "Negative means b(i) is smaller than a(i): the point is closer to a neighboring cluster than to its own — a likely misassignment.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-163", "cat": "ml", "diff": 2, "q": "A silhouette value of roughly 0 means the point…", "options": ["Lies about on a boundary between two clusters", "Is perfectly placed at a cluster center", "Must be a noise point in DBSCAN", "Belongs to the elbow"], "a": 0, "expl": "Around zero, cohesion and separation are nearly equal — the point sits between two clusters.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-164", "cat": "ml", "diff": 2, "q": "The video computes averages for K=2..6 of 0.704, 0.588, 0.650, 0.563, 0.45. Which K has the top average?", "options": ["K=3 with 0.588", "K=4 with 0.650", "K=6 with 0.45", "K=2 with 0.704"], "a": 3, "expl": "0.704 is the largest average, so K=2 tops the single-number leaderboard.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-165", "cat": "ml", "diff": 1, "q": "Despite K=2 winning on the average, the video chose K=4. Why?", "options": ["K=4 per-cluster bars were all positive AND it matched the elbow method", "K=4 had the highest average score", "K=2 is mathematically impossible here", "A lower silhouette is always better"], "a": 0, "expl": "A high average can hide a cluster full of negative-scoring points. K=4 showed all-positive per-cluster bars and agreed with the elbow — stronger combined evidence.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-166", "cat": "ml", "diff": 3, "q": "Which sklearn call gives the per-point values used to draw per-cluster silhouette bars?", "options": ["silhouette_score(X, labels)", "KMeans().fit_transform(X)", "elbow_samples(X, labels)", "silhouette_samples(X, labels)"], "a": 3, "expl": "silhouette_score returns one average; silhouette_samples returns per-point values so you can spot negative pockets inside individual clusters.", "remedy": "Notes + quiz: ../krish-ml-6h/20-silhouette.html"}, {"id": "ml-167", "cat": "ml", "diff": 2, "q": "What does DBSCAN stand for?", "options": ["Distance-Based Segmentation of Clusters and Neighbors", "Density-Based Spatial Clustering of Applications with Noise", "Dynamic Binning of Samples by Cluster Numbers", "Deep Bayesian Cluster Analysis of Networked Samples"], "a": 1, "expl": "The name encodes both ideas: clustering by density, plus an explicit Noise category for outliers.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-168", "cat": "ml", "diff": 1, "q": "Which two hyperparameters does DBSCAN need?", "options": ["K and the number of iterations", "Learning rate and epochs", "Epsilon (the radius) and MinPts (minimum points to count as dense)", "WCSS threshold and dendrogram height"], "a": 2, "expl": "Epsilon draws a neighborhood radius around each point; MinPts sets how many points inside epsilon make the area dense.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-169", "cat": "ml", "diff": 2, "q": "A CORE point is one that has…", "options": ["At least MinPts neighbors within epsilon", "Exactly one neighbor within epsilon", "Zero neighbors but a large epsilon", "More than K assigned centroids"], "a": 0, "expl": "Core points anchor clusters: their epsilon-neighborhood holds at least MinPts points, so the region counts as dense.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-170", "cat": "ml", "diff": 2, "q": "A BORDER point is one that…", "options": ["Lies farther than epsilon from every other point", "Has fewer than MinPts neighbors but lies within epsilon of a core point", "Has the maximum number of neighbors in the dataset", "Is removed from the dataset before clustering"], "a": 1, "expl": "Border points are not dense enough to be cores, but they fall inside the epsilon-neighborhood of one, so they join that cluster on its edge.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-171", "cat": "ml", "diff": 1, "q": "What happens to a NOISE point?", "options": ["It is assigned to the nearest centroid", "It becomes its own mandatory cluster", "It is treated as an outlier and is not forced into any cluster", "It is averaged into the nearest border point"], "a": 2, "expl": "Noise points sit in no dense region, so DBSCAN labels them outliers and leaves them out — the opposite of K-means, which must absorb every point.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-172", "cat": "ml", "diff": 3, "q": "Which algorithm refuses to assign noise points to any cluster?", "options": ["Both assign every point", "Neither assigns every point", "K-means", "DBSCAN"], "a": 3, "expl": "K-means forces every point into a cluster; only DBSCAN has an explicit noise/outlier label.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-173", "cat": "ml", "diff": 2, "q": "What is the shape-related superpower of DBSCAN over K-means?", "options": ["It can only find circular clusters", "It turns any shape into a convex blob", "It requires all clusters to be the same size", "It finds arbitrarily shaped clusters, while K-means carves the space into convex blobs"], "a": 3, "expl": "Because clusters grow by connected density, DBSCAN follows rings, moons and snakes; K-means assigns by nearest centroid, so it always yields convex blobs.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-174", "cat": "ml", "diff": 1, "q": "Interview: your customer data contains heavy outliers. Why is that a problem for K-means specifically?", "options": ["Every point must join a cluster, so outliers drag the centroids away from the real groups", "K-means has no epsilon parameter to protect it", "Outliers make Euclidean distance undefined", "K-means labels outliers as noise, hiding them from view"], "a": 0, "expl": "K-means recomputes each centroid as the mean of ALL its assigned points, so extreme values pull it off-center — the same reason outlier handling mattered in my churn model.", "remedy": "Notes + quiz: ../krish-ml-6h/21-dbscan.html"}, {"id": "ml-175", "cat": "ml", "diff": 2, "q": "What does inertia_ from sklearn’s KMeans represent?", "options": ["Silhouette of the best point", "WCSS — within-cluster sum of squared distances to centroids", "Number of iterations run", "The label array"], "a": 1, "expl": "inertia_ is the WCSS the elbow method plots; it always decreases as K grows.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-176", "cat": "ml", "diff": 2, "q": "Why is WCSS alone a bad way to choose K?", "options": ["It is too expensive to compute", "WCSS keeps falling as K increases — it hits 0 at K = number of points", "It ignores Euclidean distance", "It only works for 2 clusters"], "a": 1, "expl": "More clusters trivially lower WCSS; you look for the ELBOW (bend), not the minimum.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-177", "cat": "ml", "diff": 1, "q": "In the video’s silhouette comparison (K=2..6 → 0.704, 0.588, 0.650, 0.563, 0.45), which K had the highest average score?", "options": ["K=2", "K=4", "K=6", "K=5"], "a": 0, "expl": "K=2 scored 0.704 — the top average — yet the final choice was K=4 for the reasons below.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-178", "cat": "ml", "diff": 3, "q": "Why was K=4 chosen over the higher-scoring K=2?", "options": ["Random preference", "K=4 had no negative per-cluster silhouette bars and matched the elbow; more segments generalize better", "0.650 is bigger than 0.704", "K=2 had zero points"], "a": 1, "expl": "Average score + per-cluster negatives + elbow + business actionability — layered evidence picked K=4.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-179", "cat": "ml", "diff": 2, "q": "What does a NEGATIVE per-cluster silhouette bar tell you?", "options": ["That cluster is perfect", "Some points are closer to another cluster — likely misassigned", "There are too few features", "WCSS is zero"], "a": 1, "expl": "Negative s(i) means b(i) < a(i): the point fits a NEIGHBORING cluster better than its own.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-180", "cat": "ml", "diff": 1, "q": "make_blobs(centers=4) is used in the practical because…", "options": ["It guarantees hard examples", "The ground-truth cluster count is known, so methods can be judged", "It avoids using NumPy", "It replaces KMeans"], "a": 1, "expl": "Synthetic blobs with known centers let you check whether elbow/silhouette recover the truth.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-181", "cat": "ml", "diff": 2, "q": "The video’s rule when two K values are both viable is to prefer…", "options": ["Always the smallest K", "Always the largest K", "More clusters — finer segments generalize better", "No preference at all"], "a": 2, "expl": "Given both are defensible, more clusters generalize better to new data (and map to more actionable segments).", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-182", "cat": "ml", "diff": 2, "q": "How does this practical map to your MyOperator segmentation work?", "options": ["It doesn’t", "Same method chain — k-means + K selection evidence — at 100K+ profiles for targeted campaigns", "Only the make_blobs part", "It used supervised learning instead"], "a": 1, "expl": "Your resume line (k-means segmentation across 100K+ profiles) is this exact practical at production scale.", "remedy": "Notes + quiz: ../krish-ml-6h/22-clustering-practical.html"}, {"id": "ml-183", "cat": "ml", "diff": 1, "q": "Bias measures error with respect to…", "options": ["The test set only", "How well the model fits the TRAINING data", "The number of features", "The size of the hard disk"], "a": 1, "expl": "Fails on train = high bias; fits train well = low bias.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-184", "cat": "ml", "diff": 3, "q": "Variance measures…", "options": ["How much performance changes on different (test/new) data", "Training speed", "The model file size", "The bias of the dataset"], "a": 1, "expl": "Good on test = low variance; collapses on new data = high variance.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-185", "cat": "ml", "diff": 2, "q": "A model scoring train 90 / test 75 is…", "options": ["Generalized", "Underfit", "Overfit — low bias, high variance", "Perfect"], "a": 2, "expl": "Strong on train, weak on test = memorization: the classic overfit signature.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-186", "cat": "ml", "diff": 1, "q": "A model scoring train 60 / test 55 is…", "options": ["Overfit", "Generalized", "Underfit — high bias, high variance", "Impossible"], "a": 2, "expl": "Fails even on training data: too simple, high bias; and it doesn’t transfer either.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-187", "cat": "ml", "diff": 2, "q": "The GOAL state in the bias-variance framework is…", "options": ["High bias + high variance", "Low bias + low variance = generalized", "Low bias + high variance", "High bias + low variance"], "a": 1, "expl": "Like the video’s 90/92 example: fits train well AND transfers — that’s a generalized model.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-188", "cat": "ml", "diff": 2, "q": "Your model is overfit. The most on-brand fixes are…", "options": ["Add more features, train longer", "Regularize (Ridge/Lasso/λ), simplify/prune, get more data", "Remove the test set", "Lower the training accuracy"], "a": 1, "expl": "Overfit = low bias + high variance → pull variance down: regularization, pruning, more data.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-189", "cat": "ml", "diff": 1, "q": "In your reco engine, which design choice directly guards the variance side?", "options": ["Tuning SVD reg_all and α on VALIDATION only, touching test once", "Training on the test set", "Using the largest possible n_factors", "Never evaluating"], "a": 1, "expl": "Validation-only tuning + a regularization grid = engineered protection against overfitting.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-190", "cat": "ml", "diff": 3, "q": "Why do deep learning practitioners use Adam or RMSprop?", "options": ["To create local minima", "Neural cost surfaces have local minima — these optimizers navigate them better", "To increase bias", "They replace the dataset"], "a": 1, "expl": "Unlike linear regression’s convex parabola, NN surfaces are non-convex; smarter optimizers handle that.", "remedy": "Notes + quiz: ../krish-ml-6h/23-bias-variance.html"}, {"id": "ml-191", "cat": "ml", "diff": 2, "q": "XGBoost’s base model for binary classification predicts…", "options": ["The class mean", "0.5 for every single row", "A random class", "The most frequent class"], "a": 1, "expl": "The video starts every row at 0.5 (a blind coin-flip probability); trees then correct the residuals.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-192", "cat": "ml", "diff": 1, "q": "A residual in this context is…", "options": ["y − prediction", "prediction − y always positive", "The learning rate", "A leaf’s similarity"], "a": 0, "expl": "Residual = y − predicted value; the next tree is trained to predict these residuals.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-193", "cat": "ml", "diff": 2, "q": "The similarity score formula (λ = regularization) is…", "options": ["Σ residuals² / (Σ p(1−p) + λ)", "Σ residuals / n", "mean(residuals) × λ", "1 / Σ residuals²"], "a": 0, "expl": "Higher similarity = purer group. λ in the denominator shrinks the score (regularization).", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-194", "cat": "ml", "diff": 2, "q": "With λ = 1, a leaf containing a single residual of 0.5 has similarity…", "options": ["0.25", "0.5", "1.0", "0.14"], "a": 2, "expl": "0.5² / (0.5·0.5 + 1) = 0.25/0.25 = 1.0 — the video’s worked leaf.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-195", "cat": "ml", "diff": 1, "q": "Gain of a split equals…", "options": ["left sim + right sim − root sim", "root sim × leaf sim", "left − right only", "total error × α"], "a": 0, "expl": "Video worked example: 0.33 + 0 − 0.14 = 0.19 for one split; 1.33 for a better deeper split.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-196", "cat": "ml", "diff": 3, "q": "Inference starts from log-odds = 0, which corresponds to a probability of…", "options": ["0", "0.25", "0.5", "1.0"], "a": 2, "expl": "log(p/(1−p)) = 0 ⇔ p = 0.5 — the neutral starting point before adding tree outputs.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-197", "cat": "ml", "diff": 2, "q": "After walking the tree, the leaf output is added to the log-odds multiplied by…", "options": ["λ, the regularization", "α, the learning rate", "The number of rows", "The residual"], "a": 1, "expl": "α (learning rate) scales each tree’s correction — smaller α = safer sequential updates.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-198", "cat": "ml", "diff": 1, "q": "The final probability is produced by passing the updated log-odds through…", "options": ["A linear function", "The sigmoid", "Softmax over 1000 classes", "No function at all"], "a": 1, "expl": "Sigmoid converts the accumulated log-odds into a probability in (0,1).", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-199", "cat": "ml", "diff": 2, "q": "Why are λ and α tuned with cross-validation?", "options": ["They are not — they are random", "To control overfitting and step size against unseen data", "Because sklearn forbids defaults", "To make training slower"], "a": 1, "expl": "λ shrinks leaf influence, α damps each tree’s correction; CV finds values that generalize.", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-200", "cat": "ml", "diff": 2, "q": "An interviewer says “XGBoost is a black box.” Your strongest response is…", "options": ["Deny it completely", "Agree — it trades transparency for accuracy; controls are regularization + CV, and you productionized it with monitoring and safe rollbacks", "Switch the topic to SQL", "Claim linear models are also black boxes"], "a": 1, "expl": "Own the limitation, show the control mechanisms, and add your production credibility (drift monitoring, rollbacks).", "remedy": "Notes + quiz: ../krish-ml-6h/24-xgboost-classifier.html"}, {"id": "ml-201", "cat": "ml", "diff": 1, "q": "XGBoost Regressor’s base model predicts…", "options": ["0.5 for every row", "The MEAN of all target values", "The median class", "Zero"], "a": 1, "expl": "For continuous targets the blind start is the mean (video example: 51k); residuals are computed from it.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-202", "cat": "ml", "diff": 3, "q": "The similarity score for regression is…", "options": ["Σ residuals² / (n + λ)", "Σ p(1−p) × λ", "mean residual × n", "sigmoid(residuals)"], "a": 0, "expl": "Same shape as the classifier but with n (count) instead of p(1−p) — λ regularizes.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-203", "cat": "ml", "diff": 2, "q": "With λ = 0, a leaf holding a single point with residual 11 has similarity…", "options": ["121", "11", "60.5", "28.8"], "a": 0, "expl": "11² / (1 + 0) = 121 — with λ = 0 the denominator is just n = 1. The video first shows λ = 0, then λ = 1 to demonstrate shrinkage (121 → 60.5).", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-204", "cat": "ml", "diff": 1, "q": "A gain of 89 for one split vs 243.58 for another means…", "options": ["Keep the 89 split — smaller is safer", "Keep the 243.58 split — higher gain = better separation", "Neither; XGBoost picks randomly", "Both splits are invalid"], "a": 1, "expl": "Gain = how much purity improves; XGBoost always keeps the higher-gain split.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-205", "cat": "ml", "diff": 2, "q": "The output value stored in a regression leaf is…", "options": ["The mean residual of its samples", "The max target", "The similarity score", "Always zero"], "a": 0, "expl": "Leaves hold the average residual; inference adds α × that to the base mean.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-206", "cat": "ml", "diff": 2, "q": "Final prediction for a house = …", "options": ["base mean + α × leaf average residual", "base mean only", "leaf similarity + residual", "α × λ"], "a": 0, "expl": "Video example: 51k + (−10) or +7 — sequential corrections, damped by the learning rate α.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-207", "cat": "ml", "diff": 1, "q": "What happens after the first tree is built?", "options": ["Training stops", "A new tree is built on the UPDATED residuals, sequentially", "All trees are built in parallel", "The residuals are deleted"], "a": 1, "expl": "Boosting = sequential: each tree attacks what the previous ones still got wrong.", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-208", "cat": "ml", "diff": 3, "q": "λ in the similarity formula makes leaves smaller when…", "options": ["λ increases — a regularization effect", "λ decreases to 0", "n increases", "Targets are integers"], "a": 0, "expl": "Bigger λ → smaller similarity → smaller, more conservative leaf corrections (anti-overfit).", "remedy": "Notes + quiz: ../krish-ml-6h/25-xgboost-regressor.html"}, {"id": "ml-209", "cat": "ml", "diff": 2, "q": "The SVM decision for a new point is based on…", "options": ["The sign of wᵀx + b", "The magnitude of wᵀx + b", "The point’s nearest neighbor", "Random assignment"], "a": 0, "expl": "Sign of wᵀx + b picks the side: video example, w=[−1], b=0 → point (−4,0) gives +4 → class A.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-210", "cat": "ml", "diff": 1, "q": "The two marginal planes are defined as…", "options": ["wᵀx + b = 0 and wᵀx + b = 1", "wᵀx + b = ±1", "wᵀx + b = ±2/||w||", "w = 0"], "a": 1, "expl": "The margin planes are wᵀx + b = ±1; the separating hyperplane sits at 0 between them.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-211", "cat": "ml", "diff": 2, "q": "What are support vectors?", "options": ["All training points", "The points touching the marginal planes that define the boundary", "Only the misclassified points", "The cluster centroids"], "a": 1, "expl": "Support vectors touch the margin planes; remove every other point and the boundary is unchanged.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-212", "cat": "ml", "diff": 2, "q": "SVM’s objective is to…", "options": ["Minimize the margin", "Maximize the margin 2/||w||", "Minimize the number of features", "Maximize ξ"], "a": 1, "expl": "Widest street between classes = best generalization; maximizing 2/||w|| ⇔ minimizing ||w||.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-213", "cat": "ml", "diff": 1, "q": "The soft-margin objective adds which term?", "options": ["C · Σξᵢ — a penalty for margin violations", "α · learning rate", "A sigmoid activation", "The silhouette score"], "a": 0, "expl": "ξᵢ measures how badly each point violates the margin; C prices those violations.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-214", "cat": "ml", "diff": 3, "q": "A LARGE value of C means…", "options": ["Very tolerant of errors — wide margin", "Strict about errors — narrow margin, overfit risk", "No hyperplane is found", "Kernels are disabled"], "a": 1, "expl": "Big C punishes violations heavily → fits training tightly, risking overfit; small C is forgiving.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-215", "cat": "ml", "diff": 2, "q": "Kernels are used when…", "options": ["Data is already linearly separable", "Data is not separable in the current dimension — lift it higher (2D → 3D)", "You want fewer support vectors", "The dataset is too small"], "a": 1, "expl": "The kernel trick maps data to a higher dimension where a flat separating plane exists.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}, {"id": "ml-216", "cat": "ml", "diff": 1, "q": "A HARD margin (zero training errors) is rare in practice because…", "options": ["SVM cannot compute it", "Real data almost always overlaps between classes", "It requires deep learning", "Margins are illegal"], "a": 1, "expl": "Real datasets have noise/overlap — hence the soft margin with slack ξ and penalty C.", "remedy": "Notes + quiz: ../krish-ml-6h/26-svm.html"}];
